104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        List<String> missingFields = new ArrayList<>();
108	        if (isBlank(ownerFieldsDto.getFirstName())) {
109	            missingFields.add("firstName");
110	        }
111	        if (isBlank(ownerFieldsDto.getLastName())) {
112	            missingFields.add("lastName");
113	        }
114	        if (isBlank(ownerFieldsDto.getAddress())) {
115	            missingFields.add("address");
116	        }
117	        if (isBlank(ownerFieldsDto.getCity())) {
118	            missingFields.add("city");
119	        }
120	        if (isBlank(ownerFieldsDto.getTelephone())) {
121	            missingFields.add("telephone");
122	        }
123	        if (!missingFields.isEmpty()) {
124	            throw new MissingOwnerFieldsException(missingFields);
125	        }
126	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
127	        if (isTelephoneInUse(telephone)) {
128	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
129	        }
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setTelephone(telephone);
